+/// Normalizes a co-Z odd-multiple table of `base` with a single inversion.
+///
+/// The inverses of earlier entries follow from the chain factors. The chain
+/// starts from 2P with `Z = 2Y * Z(P)`, so the inverse `Z` of `base` is
+/// `2Y` times the inverse `Z` of 2P.
+fn normalize_co_z_table<const N: usize>(
+    base: ProjectivePoint,
+    table: &[ProjectivePoint; N],
+    factors: &[FieldElement; N],
+) -> [AffinePoint; N] {
+    let Some(mut z_inverse) = table[N - 1].z.invert() else {
+        return batch_normalize(*table);
+    };
+    let mut out = [AffinePoint::IDENTITY; N];
+
+    for k in (1..N).rev() {
+        let z_inverse2 = z_inverse.square();
+        out[k] = AffinePoint {
+            x: table[k].x * z_inverse2,
+            y: table[k].y * z_inverse2 * z_inverse,
+            infinity: false,
+        };
+        z_inverse = z_inverse * factors[k];
+    }
+
+    let z_inverse = z_inverse * double(base.y);
+    let z_inverse2 = z_inverse.square();
+    out[0] = AffinePoint {
+        x: base.x * z_inverse2,
+        y: base.y * z_inverse2 * z_inverse,
+        infinity: false,
+    };
+
+    out
+}
